// src/facets/waves.rs — the facet's own module; src/main.rs adds its two FACET WIRING lines.
// World (src/main.rs) holds lane: usize, wave: usize, z: f32, targets: Vec<Vec3> and near: bool;
// the game's ActionMap binds SWITCH to Space.
use super::World;
use genex::actions::ActionId;
use genex::prelude::*;
use genex::profile::ScopeName;

const SWITCH: ActionId = ActionId::new("switch");
const WAVE: ScopeName = ScopeName::new("wave");
const LANES: usize = 3;
/// Each wave's speed; the world's wave never passes the last.
const SPEEDS: [f32; 3] = [4.0, 6.0, 9.0];
/// Ticks between waves.
const WAVE_TICKS: u64 = 600;

pub fn wire(game: &mut Game<World>) {
    game.on_update(|sim, ctx| {
        genex::profile_scope!("waves"); // the record's profile summary names this scope
        // Input only through the tick (actions or keys), so the record's replay holds it.
        if ctx.actions.fired(SWITCH) {
            sim.world.lane = (sim.world.lane + 1) % LANES;
        }
        if ctx.tick % WAVE_TICKS == WAVE_TICKS - 1 && sim.world.wave + 1 < SPEEDS.len() {
            sim.world.wave += 1;
        }
        // A broken rule panics naming the rule: the record's message and line say what broke.
        let speed = *SPEEDS.get(sim.world.wave).expect("the wave stops at the last speed");
        sim.world.z += speed * ctx.dt;
        genex::profile::counter(WAVE, sim.world.wave as f64);
        // What may be missing is guarded, never unwrapped: a crash is then always a real bug.
        let Some(target) = sim.world.targets.first() else { return };
        sim.world.near = (target.z - sim.world.z).abs() < 1.0;
    });
    game.probe("waves", |sim| json!({ "wave": sim.world.wave, "lane": sim.world.lane }));
    // After a fix: walk the input path the record kept, so every later look replays it.
    game.demo("switch-past-a-wave", |d| {
        d.inject(Input::key_tap(Key::Space));
        d.advance_ms(10_500); // past tick 600, where the wave changes
        json!({ "wave": d.sim().world.wave, "lane": d.sim().world.lane })
    });
}
